function PeekOverlay({ peekWindow, isPeekClosing, closePeek, isForceDark, isIncognito }) {
    const peekRef = React.useRef(null);
    const dk = isForceDark || isIncognito;

    // Close on Escape
    React.useEffect(() => {
        const handleKeyDown = (e) => {
            if (e.key === 'Escape') closePeek();
        };
        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [closePeek]);

    // Create a native webview for the peek content
    React.useEffect(() => {
        if (!peekWindow?.url || !peekRef.current) return;

        const rect = peekRef.current.getBoundingClientRect();
        let targetUrl = peekWindow.url;
        if (!targetUrl.startsWith('http://') && !targetUrl.startsWith('https://')) {
            targetUrl = `https://${targetUrl}`;
        }

        import('../../services/tauriIPC').then(({ createTabWebview, closeTabWebview, setTabWebviewBounds }) => {
            createTabWebview('peek_preview', targetUrl, rect.x, rect.y, rect.width, rect.height).catch(console.error);

            // Update bounds after a short delay for layout
            setTimeout(() => {
                if (peekRef.current) {
                    const r = peekRef.current.getBoundingClientRect();
                    setTabWebviewBounds('peek_preview', r.x, r.y, r.width, r.height).catch(console.error);
                }
            }, 200);
        });

        return () => {
            import('../../services/tauriIPC').then(({ closeTabWebview }) => {
                closeTabWebview('peek_preview').catch(console.error);
            });
        };
    }, [peekWindow?.url]);

    return (
        <>
            {/* Backdrop — click to close */}
            <div className="absolute inset-0 z-[999]" onClick={closePeek} />
            <div className={`absolute inset-8 md:inset-16 z-[1000] flex flex-col rounded-2xl shadow-[0_40px_100px_rgba(0,0,0,0.5)] overflow-hidden border ${dk ? 'bg-[#0a0a0c] border-white/10' : 'bg-white border-gray-200'} ${isPeekClosing ? 'animate-pop-out' : 'animate-pop-in'}`}>
                {/* Peek Header */}
                <div className={`flex items-center gap-3 px-4 py-3 border-b ${dk ? 'border-white/10 bg-black/40' : 'border-gray-200 bg-gray-50'}`}>
                    <button onClick={closePeek} className="w-3.5 h-3.5 bg-red-500 hover:bg-red-400 rounded-full flex items-center justify-center group transition shadow-sm">
                        <X size={8} className="opacity-0 group-hover:opacity-100 text-black" />
                    </button>
                    <div className={`flex-1 flex items-center gap-2 px-3 py-1 rounded-lg ${dk ? 'bg-white/5 border border-white/5' : 'bg-gray-100 border border-gray-200'}`}>
                        <ExternalLink size={12} className={dk ? 'text-white/30' : 'text-gray-400'} />
                        <span className={`text-xs font-mono truncate ${dk ? 'text-white/60' : 'text-gray-500'}`}>{peekWindow?.url || 'about:blank'}</span>
                    </div>
                    <span className={`text-[9px] font-bold uppercase tracking-wider ${dk ? 'text-white/30' : 'text-gray-400'}`}>Peek</span>
                </div>
                {/* Peek Content — this is where the native webview renders */}
                <div ref={peekRef} className="flex-1 relative">
                    <div className={`absolute inset-0 flex items-center justify-center ${dk ? 'text-white/20' : 'text-gray-300'}`}>
                        <div className="flex flex-col items-center gap-3 animate-pulse">
                            <Globe size={32} />
                            <span className="text-xs font-bold uppercase tracking-widest">Loading Preview...</span>
                        </div>
                    </div>
                </div>
            </div>
        </>
    );
}

